<script setup lang="ts">
import { onMounted, reactive, ref } from 'vue'
import { cambiarEstadoCurso, guardarCurso, listarCentrosActivos, listarCursos } from '../services/cursosCapacitaciones'
import type { CentroOption, CursoCapacitacion, CursoPayload } from '../interfaces/cursosCapacitaciones.interface'
const rows=ref<CursoCapacitacion[]>([]),centers=ref<CentroOption[]>([]),criterio=ref(''),page=ref(1),lastPage=ref(1),total=ref(0),loading=ref(false),saving=ref(false),error=ref(''),success=ref(''),modal=ref(false),editing=ref<number|null>(null)
const form=reactive<CursoPayload>({codigo:'',centro_id:null,nombre:''})
const message=(v:unknown)=>v instanceof Error?v.message:'No se pudo completar la operación.'
async function load(next=1){loading.value=true;error.value='';try{const r=await listarCursos(criterio.value,next);rows.value=r.data;page.value=r.current_page;lastPage.value=r.last_page;total.value=r.total}catch(v){error.value=message(v)}finally{loading.value=false}}
async function loadCenters(){if(centers.value.length)return;try{centers.value=await listarCentrosActivos()}catch(v){error.value=message(v)}}
async function open(item?:CursoCapacitacion){editing.value=item?.id??null;Object.assign(form,{codigo:item?.codigo??'',centro_id:item?.centro_id??null,nombre:item?.nombre??''});error.value='';modal.value=true;await loadCenters()}
async function save(){const codigo=form.codigo.trim().toUpperCase(),nombre=form.nombre.trim().toUpperCase();if(!codigo)return void(error.value='El código es obligatorio.');if(codigo.length>10)return void(error.value='El código admite como máximo 10 caracteres.');if(!form.centro_id)return void(error.value='Debe seleccionar un centro de enseñanza.');if(nombre.length<3)return void(error.value='El nombre debe tener al menos 3 caracteres.');saving.value=true;error.value='';try{await guardarCurso(editing.value,{codigo,centro_id:form.centro_id,nombre});modal.value=false;success.value=`Curso o capacitación ${editing.value?'actualizado':'registrado'} correctamente.`;await load(editing.value?page.value:1)}catch(v){error.value=message(v)}finally{saving.value=false}}
async function toggle(item:CursoCapacitacion){const action=item.estado?'desactivar':'activar';if(!confirm(`¿Desea ${action} ${item.nombre}?`))return;try{const r=await cambiarEstadoCurso(item.id);item.estado=r.estado;success.value=r.message??`Curso ${item.estado?'activado':'desactivado'} correctamente.`}catch(v){error.value=message(v)}}
onMounted(()=>load())
</script>
<template><div class="page"><nav><RouterLink to="/inicio">Inicio</RouterLink> / Administración / Recursos Humanos / Cursos y capacitaciones</nav><header class="hero"><div class="mark">CC</div><div><small>MIA · RECURSOS HUMANOS · MAESTROS</small><h1>Cursos y capacitaciones</h1><p>Catálogo de formación complementaria vinculada a centros de enseñanza.</p></div><strong>{{total}} registros</strong><button @click="open()">+ Nuevo curso</button></header><p v-if="success" class="flash success">✓ {{success}}</p><p v-if="error" class="flash">{{error}}</p><form class="filters" @submit.prevent="load(1)"><label>Buscar por código, nombre o centro<input v-model.trim="criterio" placeholder="Ej. EXCEL, SEGURIDAD o ESAN"></label><button>Buscar</button><button type="button" class="soft" @click="criterio='';load(1)">Limpiar</button></form><section class="table-card"><header><div><small>MAESTRO DE FORMACIÓN</small><h2>Cursos y capacitaciones registrados</h2></div></header><div v-if="loading" class="empty">Consultando cursos…</div><div v-else-if="!rows.length" class="empty">No se encontraron cursos o capacitaciones.</div><div v-else class="scroll"><table><thead><tr><th>#</th><th>Código</th><th>Nombre</th><th>Centro de enseñanza</th><th>Estado</th><th>Acciones</th></tr></thead><tbody><tr v-for="item in rows" :key="item.id"><td>{{item.id}}</td><td><b>{{item.codigo}}</b></td><td>{{item.nombre}}</td><td>{{item.centro?.nombre??'Sin especificar'}}</td><td><span :class="item.estado?'active':'inactive'">{{item.estado?'Activo':'Inactivo'}}</span></td><td class="actions"><button class="edit" @click="open(item)">Editar</button><button :class="item.estado?'disable':'enable'" @click="toggle(item)">{{item.estado?'Desactivar':'Activar'}}</button></td></tr></tbody></table></div><footer v-if="lastPage>1"><button :disabled="page<=1" @click="load(page-1)">Anterior</button><span>Página {{page}} de {{lastPage}}</span><button :disabled="page>=lastPage" @click="load(page+1)">Siguiente</button></footer></section><div v-if="modal" class="backdrop" @mousedown.self="modal=false"><form class="dialog" @submit.prevent="save"><header><div class="mark">CC</div><div><small>MAESTRO DE FORMACIÓN</small><h2>{{editing?'Editar':'Registrar'}} curso o capacitación</h2></div><button type="button" @click="modal=false">×</button></header><div class="grid"><label>Código *<input v-model="form.codigo" maxlength="10" @input="form.codigo=form.codigo.toUpperCase()"></label><label>Centro de enseñanza *<select v-model="form.centro_id" required><option :value="null">Seleccione un centro</option><option v-for="center in centers" :key="center.id" :value="center.id">{{center.nombre}}</option></select></label><label class="wide">Nombre del curso o capacitación *<input v-model="form.nombre" maxlength="250" @input="form.nombre=form.nombre.toUpperCase()"></label></div><footer><button type="button" class="soft" @click="modal=false">Cancelar</button><button :disabled="saving">{{saving?'Guardando…':editing?'Actualizar':'Registrar'}}</button></footer></form></div></div></template>
<style scoped>
.page{--accent:#d64f83;color:#35464e}nav{margin-bottom:16px;color:#929fa5;font-size:.68rem}nav a{color:var(--accent);text-decoration:none}.hero{padding:20px 23px;display:flex;align-items:center;gap:14px;border-left:5px solid var(--accent);border-radius:12px;background:#fff}.mark{width:48px;height:48px;display:grid;place-items:center;border-radius:10px;color:#fff;background:var(--accent);font-size:.65rem;font-weight:800}.hero small,.table-card small,.dialog small{color:var(--accent);font-size:.48rem;font-weight:800}.hero h1{margin:2px 0;font-size:1.3rem}.hero p{margin:0;color:#7e8a90;font-size:.67rem}.hero strong{margin-left:auto;padding:6px 9px;border-radius:12px;color:var(--accent);background:#fff0f5;font-size:.52rem}.hero button,.filters button,.table-card footer button,.dialog button{padding:9px 12px;border:0;border-radius:6px;color:#fff;background:var(--accent);font-size:.52rem}.flash{padding:9px;border-radius:7px;color:#a64046;background:#fff0f0;font-size:.6rem}.flash.success{color:#287052;background:#edf9f3}.filters{margin-top:10px;padding:13px;display:flex;align-items:end;gap:6px;border-radius:9px;background:#fff}.filters label{margin-right:auto;width:min(460px,100%);font-size:.52rem}.filters input,.dialog input,.dialog select{width:100%;box-sizing:border-box;margin-top:4px;padding:8px;border:1px solid #d7dfe2;border-radius:6px;background:#fff;font:inherit;font-size:.54rem}.soft{color:#64727a!important;background:#edf1f3!important}.table-card{margin-top:10px;border-radius:10px;background:#fff;overflow:hidden}.table-card>header{padding:13px 15px;border-bottom:1px solid #e7ebed}.table-card h2{margin:2px 0;font-size:.78rem}.scroll{overflow:auto}table{width:100%;border-collapse:collapse;font-size:.54rem}th,td{padding:10px;border-bottom:1px solid #e8ecee;text-align:left}th{color:#fff;background:#5b6e8e}.active,.inactive{display:inline-block;padding:4px 7px;border-radius:10px;font-size:.44rem}.active{color:#287154;background:#e6f7ee}.inactive{color:#9d4046;background:#fdebed}.actions{display:flex;gap:5px}.actions button{padding:6px 8px;border:0;border-radius:5px;font-size:.46rem}.edit{color:#79500b;background:#ffe7bd}.disable{color:#9d4046;background:#fdebed}.enable{color:#287154;background:#e6f7ee}.empty{padding:45px;text-align:center;font-size:.6rem}.table-card>footer{padding:10px;display:flex;justify-content:center;align-items:center;gap:9px;font-size:.52rem}.backdrop{position:fixed;z-index:100;inset:0;padding:20px;display:grid;place-items:center;background:#172b3d88}.dialog{width:min(720px,100%);padding:20px;box-sizing:border-box;border-radius:12px;background:#fff}.dialog>header{display:flex;align-items:center;gap:9px}.dialog h2{margin:2px 0 12px;font-size:.9rem}.dialog>header>button{margin-left:auto;color:#59666c;background:none;font-size:1.2rem}.dialog label{display:grid;margin-top:10px;font-size:.5rem}.grid{display:grid;grid-template-columns:1fr 2fr;gap:9px}.wide{grid-column:1/-1}.dialog>footer{margin-top:16px;display:flex;justify-content:flex-end;gap:6px}@media(max-width:760px){.hero,.filters{flex-wrap:wrap}.hero strong{margin-left:0}.filters label{width:100%}.grid{grid-template-columns:1fr}.wide{grid-column:auto}.actions{min-width:140px}}
</style>
